{
  "passageId": "giddens-beck-risk-society",
  "items": [
    {
      "id": "R1",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "기든스가 기존 두 입장의 구조관과 인간관에 결함이 있다고 문제 삼으므로 관점 사이의 비판에 해당한다."
    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "기존 입장들의 이분법적 한계를 지적하고 이를 보완할 대안으로 구조화 이론을 제시한다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "구조화 이론을 제시한 뒤 그 이론의 구조관과 인간관을 자세히 설명한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "언어 규칙과 언어 사용은 구조가 행위의 매개이자 결과물이라는 설명을 구체적으로 보여 주는 사례이다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "언어 규칙을 활용하고 변용하는 사례에서 인간의 주체성이라는 일반적 성질로 나아간다."
    },
    {
      "id": "R6",
      "type": "CAUSE",
      "otherName": "",
      "reason": "성찰적 실천이 사회체계의 유지와 변형 및 재생산을 실제로 가능하게 하는 작용을 설명한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "성찰적 실천을 통한 사회체계 재생산이라는 설명을 행위 지속의 동력인 추상적 시스템으로 더 자세히 풀어낸다."
    },
    {
      "id": "R8",
      "type": "CAUSE",
      "otherName": "",
      "reason": "추상적 시스템이 사회체계 재생산에 필요한 개인 행위의 지속을 가능하게 하는 실제 동력으로 제시된다."
    },
    {
      "id": "R9",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "추상적 시스템의 구성 요소를 나열한 뒤 그중 상징적 표상의 의미와 사례 및 작용을 상세히 설명한다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "추상적 시스템의 구성 요소를 나열한 뒤 그중 전문가 체계의 의미와 사례 및 기능을 상세히 설명한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "사회적 관계의 확장이 낯선 환경과 타인에 대한 무지를 수반하여 불안과 불확실성을 발생시키는 작용을 설명한다."
    },
    {
      "id": "R12",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "확장된 사회적 관계에서 발생하는 불안과 불확실성에 대한 해소 방안으로 전문가 체계에 대한 믿음을 제시한다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "전문가 체계에 대한 믿음으로 불안이 해소되는 것이 사회적 관계의 지속을 가능하게 한다는 실제 작용 관계이다."
    },
    {
      "id": "R14",
      "type": "CAUSE",
      "otherName": "",
      "reason": "사회적 관계와 개인 행위의 지속 및 반복이 사회체계의 재생산으로 이어진다고 설명한다."
    },
    {
      "id": "R15",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "현대 사회의 불확실한 환경에도 불구하고 인간이 주체적으로 사회체계를 재구성할 수 있음을 강조한다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인간의 주체적 성찰과 사회체계 재생산에 관한 이론 내용이 구조화 이론의 의의를 평가하는 근거가 된다."
    },
    {
      "id": "R17",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "산업 사회의 발전이 안정과 생산성 증대를 가져오면서도 생존을 위협하는 위험을 초래했다는 양면성을 제시한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞에서 제시한 산업 사회의 위험을 그 기원과 확산 범위 및 예측·통제의 한계로 더 자세히 설명한다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "산업화가 초래한 전 지구적 위험이 안전과 생존 확보를 사회의 최우선 과제로 만드는 변화를 일으킨다."
    },
    {
      "id": "R20",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "안전과 생존 확보 및 위험 관리가 사회 운영의 중심이 된 상태를 위험사회라고 명명한다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "위험사회에 대한 일반적 설명을 위험 대응 능력과 위험 분배의 계층적 불평등이라는 세부 양상으로 구체화한다."
    },
    {
      "id": "R22",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "위험은 모든 사람에게 위협이 되지만 그 위험에 대응할 능력까지 평등한 것은 아니라는 한계를 제시한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "계층에 따른 위험 대응 능력의 차이가 위험 역시 불평등하게 분배된다는 판단을 뒷받침한다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "위험사회에 대한 일반적 설명을 과학과 전문가의 권위 및 위험 관리 구조의 변화라는 세부 양상으로 구체화한다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과학이 위험 생산에 관여한 것이 위험 정의와 관리의 독점적 권한을 상실하게 하는 원인으로 제시된다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과학의 불완전한 위험 통제가 위험 정의와 관리의 독점적 권한 상실로 이어지는 실제 변화를 설명한다."
    },
    {
      "id": "R27",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과학의 독점적 권한 상실이 과학적 지식에 의존하던 전문가의 권위 해체로 이어진다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "전문가 권위의 해체에 따라 위험 관리 구조가 전문가 독점에서 시민 참여의 다층적 체계로 변화한다."
    },
    {
      "id": "R29",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "기존 사회 구조를 점검하고 재구성하는 성찰적 근대성이 위험 극복과 안전한 삶이라는 목적을 위한 수단으로 제시된다."
    },
    {
      "id": "R30",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "위험사회가 제기하는 안전과 생존의 문제에 대한 대응으로 사회 구조를 점검하고 재구성하는 성찰적 근대성을 제시한다."
    },
    {
      "id": "R31",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "기든스는 전문가 체계에 대한 신뢰의 지속 기능에 주목하고 벡은 전문가 권위의 해체에 주목한다는 관점 차이를 보인다."
    },
    {
      "id": "R32",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "기든스와 벡 모두 인간이 기존 구조를 수동적으로 따르기만 하지 않고 성찰적으로 재구성하는 주체라는 견해를 공유한다."
    },
    {
      "id": "R33",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "두 이론 모두 불확실성과 위험 속에서 인간의 성찰적 행위가 능동적 대응의 가능성을 연다는 공통된 의의를 지닌다."
    }
  ]
}

